class LicznikInstancyjny {
    private int value = 0;
    synchronized void increment() { value++; } // blokada na `this`
}
// Dwa watki wywolujace increment() na DWOCH ROZNYCH obiektach NIE blokuja sie nawzajem
// (rozne monitory!). Blokuja sie TYLKO gdy wywoluja ja na TYM SAMYM obiekcie.

private static synchronized void incrementujStatycznie(int razy) {
    for (int i = 0; i < razy; i++) licznikStatyczny++;
}
// Blokada zakladana jest na obiekcie klasy (NazwaKlasy.class) - JEDEN taki obiekt na cala JVM,
// wiec WSZYSTKIE watki wywolujace dowolna synchronized metode STATYCZNA tej klasy
// rywalizuja o TA SAMA, WSPOLNA blokade.

private static final Object blokada = new Object();
for (int i = 0; i < 500_000; i++) {
    synchronized (blokada) {
        licznikStatyczny++;
    }
}
// KORZYSC: wezszy zakres blokady = mniejsza rywalizacja (contention),
// bo POZA blokiem synchronized watki moga pracowac ROWNOLEGLE

class SafeCounter {
    private int value = 0;
    synchronized void increment() { value++; } // sekcja krytyczna
    synchronized int getValue() { return value; }
}
// 4 watki x 500_000 increment() na WSPOLNEJ instancji SafeCounter
// -> wynik ZAWSZE poprawny i deterministyczny (w odroznieniu od Lesson07/09)

