class Licznik { int v=0; synchronized void increment() { v++; } synchronized int getValue() { return v; } }
Licznik l = new Licznik();
Thread t1 = new Thread(() -> { for (int j=0;j<100_000;j++) l.increment(); });
Thread t2 = new Thread(() -> { for (int j=0;j<100_000;j++) l.increment(); });
t1.start(); t2.start(); t1.join(10_000); t2.join(10_000);
System.out.println("oczekiwany=200000 rzeczywisty="+l.getValue());

Licznik la = new Licznik(), lb = new Licznik();
Thread ta = new Thread(() -> { for (int j=0;j<100_000;j++) la.increment(); });
Thread tb = new Thread(() -> { for (int j=0;j<100_000;j++) lb.increment(); });
ta.start(); tb.start(); ta.join(10_000); tb.join(10_000);
System.out.println(la.getValue() + " " + lb.getValue()); // oba 100000, poprawne

