class ThreadSafeStack<T> {
    List<T> dane = new ArrayList<>();
    synchronized void push(T t) { dane.add(t); }
    synchronized T pop() { return dane.remove(dane.size()-1); }
    synchronized int size() { return dane.size(); }
}
// kilka watkow push-ujacych ustalona liczbe elementow, sprawdz finalny size()

class Config {
