for (int i=0;i<4;i++) t[i] = new Thread(() -> { for (int j=0;j<1000;j++) r.a(); });
for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println("brak zakleszczenia - monitor jest reentrant");

