class BoundedBuffer {
    int[] dane = new int[100]; int size = 0;
    synchronized boolean addIfRoom(int v) { if (size >= dane.length) return false; dane[size++] = v; return true; }
    synchronized boolean removeIfAvailable() { if (size == 0) return false; size--; return true; }
}
// watek producenta wola addIfRoom() N razy, watek konsumenta wola removeIfAvailable() N razy, zweryfikuj spojnosc size

// (a) synchronized na calej metodzie increment()
