class ParkingLot {
    int capacity, occupiedSpots = 0;
    ParkingLot(int c) { capacity = c; }
    synchronized boolean enter() { if (occupiedSpots >= capacity) return false; occupiedSpots++; return true; }
    synchronized void exit() { if (occupiedSpots > 0) occupiedSpots--; }
}
// kilka watkow wywolujacych enter()/exit(), zweryfikuj 0 <= occupiedSpots <= capacity

class Statistics {
    int count=0; double sum=0, min=Double.MAX_VALUE, max=-Double.MAX_VALUE;
    synchronized void addValue(double v) { count++; sum+=v; if (v<min) min=v; if (v>max) max=v; }
}
// podziel ustalona tablice losowych wartosci miedzy 4 watki, porownaj z sekwencyjnym obliczeniem

class Cache<K,V> {
    Map<K,V> mapa = new LinkedHashMap<>();
    synchronized V get(K k) { return mapa.get(k); }
    synchronized void put(K k, V v) { mapa.put(k, v); }
}
// ustalona sekwencja operacji put/get z wielu watkow, zweryfikuj brak wyjatkow i poprawny size()

class BankAccount { int id; int balance; }
static void transfer(BankAccount a, BankAccount b, int amount) {
    BankAccount pierwszy = a.id < b.id ? a : b;
    BankAccount drugi = a.id < b.id ? b : a;
    synchronized (pierwszy) {
        synchronized (drugi) {
            a.balance -= amount; b.balance += amount;
        }
    }
}
// wiele watkow wykonujacych transfery, zweryfikuj sume sald PRZED == sume sald PO

