class MovingAverage {
    double[] bufor; int index=0, count=0;
    MovingAverage(int n) { bufor = new double[n]; }
    synchronized void addValue(double v) { bufor[index] = v; index = (index+1) % bufor.length; if (count < bufor.length) count++; }
    synchronized double getAverage() { double s=0; for (int i=0;i<count;i++) s+=bufor[i]; return s/count; }
}
// dodaj ustalona sekwencje wartosci (kontrolowana kolejnosc), porownaj z reczne wyliczona srednia

