class Warehouse {
    Map<String,Integer> stock = new HashMap<>();
    Object lock = new Object();
    boolean reserve(String item, int qty) { synchronized (lock) { int cur = stock.getOrDefault(item,0); if (cur < qty) return false; stock.put(item, cur-qty); return true; } }
    void restock(String item, int qty) { synchronized (lock) { stock.merge(item, qty, Integer::sum); } }
}
// wiele watkow wykonujacych ustalona liste operacji reserve/restock (ta sama lista tez liczona sekwencyjnie jako oczekiwany wynik)
